#pragma once
#include "../verification/fresh_fixture_helpers.hpp"
#include <array>
inline double quantile(std::vector<double> x,double p){require(!x.empty()&&p>=0&&p<=1,"Quantile domain");for(double v:x)require(std::isfinite(v),"Nonfinite observation");std::sort(x.begin(),x.end());double pos=(x.size()-1)*p;auto i=size_t(pos);return i+1<x.size()?x[i]+(pos-i)*(x[i+1]-x[i]):x[i];}
inline double mean(const std::vector<double>&x){require(!x.empty(),"No observations");long double sum=0;for(double v:x){require(std::isfinite(v),"Nonfinite observation");sum+=v;}return double(sum/x.size());}
inline std::string descriptive(const std::vector<double>&x){std::ostringstream o;o<<std::setprecision(17)<<"{\"n\":"<<x.size()<<",\"mean\":"<<mean(x)<<",\"median\":"<<quantile(x,.5)<<",\"p90\":"<<quantile(x,.9)<<",\"p95\":"<<quantile(x,.95)<<",\"max\":"<<quantile(x,1)<<"}";return o.str();}
struct Estimate{double ratio,lo,hi;};
inline std::array<Estimate,3> paired(const std::array<std::vector<double>,3>&x,uint64_t seed){auto n=x[0].size();require(n>0&&x[1].size()==n&&x[2].size()==n,"Paired block dimension mismatch");for(auto&v:x)for(double value:v)require(std::isfinite(value)&&value>0,"Nonpositive paired cost");SplitMix64 rng{seed};std::array<std::vector<double>,3> boot;for(size_t draw=0;draw<20000;draw++){std::array<long double,3> sums{};for(size_t j=0;j<n;j++){uint64_t raw;uint64_t threshold=(uint64_t(0)-uint64_t(n))%n;do{raw=rng.next();}while(raw<threshold);auto i=raw%n;for(size_t role=0;role<3;role++)sums[role]+=x[role][i];}boot[0].push_back(double(sums[1]/sums[2]));boot[1].push_back(double(sums[0]/sums[2]));boot[2].push_back(double(sums[1]/sums[0]));}return {{{mean(x[1])/mean(x[2]),quantile(boot[0],.025),quantile(boot[0],.975)},{mean(x[0])/mean(x[2]),quantile(boot[1],.025),quantile(boot[1],.975)},{mean(x[1])/mean(x[0]),quantile(boot[2],.025),quantile(boot[2],.975)}}};}
